"use client";
import React, { useState, useEffect } from 'react';
import { useWallet, useConnection } from '@solana/wallet-adapter-react';
import { WalletMultiButton } from '@solana/wallet-adapter-react-ui';
import { 
  Wallet, 
  Shield, 
  TrendingUp, 
  AlertCircle, 
  Loader, 
  Lock, 
  Eye, 
  EyeOff, 
  DollarSign, 
  Percent, 
  Clock, 
  CheckCircle,
  Activity,
  Users,
  BarChart3,
  Home,
  Trophy,
  Settings,
  Menu,
  X,
  LogOut
} from 'lucide-react';
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer 
} from 'recharts';

// Import custom hooks and utilities
import usePrivateLending from '@/app/src/hooks/usePrivateLending';
import { useNotification } from '@/app/src/contexts/NotificationContext';
import { formatCurrency, shortenAddress, getExplorerUrl } from '@/lib/utils';

// Main Unified App Component
const ArciumPrivateLending = () => {
  // Solana wallet hooks
  const wallet = useWallet();
  const { connection } = useConnection();
  
  const [activeTab, setActiveTab] = useState('lending');
  const [activeLendingTab, setActiveLendingTab] = useState('deposit');
  const [isProcessing, setIsProcessing] = useState(false);
  const [showPrivateInfo, setShowPrivateInfo] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [timeRange, setTimeRange] = useState('7d');
  
  // User state (encrypted in real implementation)
  const [userPosition, setUserPosition] = useState({
    collateralAmount: 0,
    borrowedAmount: 0,
    healthFactor: 0,
    interestRate: 0,
    liquidationThreshold: 75,
    totalXP: 1250,
    level: 5,
    streak: 12,
  });

  // Pool state
  const [poolStats, setPoolStats] = useState({
    totalLiquidity: 1250000,
    totalBorrowed: 850000,
    utilizationRate: 68,
    avgAPY: 5.8,
  });

  // Form states
  const [depositAmount, setDepositAmount] = useState('');
  const [borrowAmount, setBorrowAmount] = useState('');
  const [repayAmount, setRepayAmount] = useState('');
  const [withdrawAmount, setWithdrawAmount] = useState('');

  // Analytics data
  const healthFactorHistory = [
    { time: 'Mon', value: 1.45 },
    { time: 'Tue', value: 1.52 },
    { time: 'Wed', value: 1.48 },
    { time: 'Thu', value: 1.55 },
    { time: 'Fri', value: 1.62 },
    { time: 'Sat', value: 1.58 },
    { time: 'Sun', value: 1.65 },
  ];

  const achievements = [
    { id: 1, title: '🎯 First Steps', unlocked: true, points: 10 },
    { id: 2, title: '💎 Diamond Hands', unlocked: true, points: 200 },
    { id: 3, title: '🔥 On Fire', unlocked: true, points: 250 },
    { id: 4, title: '🐋 Whale Status', unlocked: false, points: 500 },
  ];

  // Initialize user position when wallet connects
  useEffect(() => {
    if (wallet.connected && wallet.publicKey) {
      // In a real implementation, fetch user data from Arcium MPC
      setUserPosition({
        collateralAmount: 5000,
        borrowedAmount: 3200,
        healthFactor: 1.56,
        interestRate: 6.2,
        liquidationThreshold: 75,
        totalXP: 1250,
        level: 5,
        streak: 12,
      });
    } else {
      // Reset position when wallet disconnects
      setUserPosition({
        collateralAmount: 0,
        borrowedAmount: 0,
        healthFactor: 0,
        interestRate: 0,
        liquidationThreshold: 75,
        totalXP: 1250,
        level: 5,
        streak: 12,
      });
    }
  }, [wallet.connected, wallet.publicKey]);

  // Calculate health factor
  const calculateHealthFactor = (collateral, borrowed, threshold = 75) => {
    if (borrowed === 0) return 999;
    return (collateral * (threshold / 100)) / borrowed;
  };

  // Deposit collateral
  const handleDeposit = async () => {
    if (!depositAmount || parseFloat(depositAmount) <= 0) return;
    
    setIsProcessing(true);
    await new Promise(resolve => setTimeout(resolve, 2000));
    
    const newCollateral = userPosition.collateralAmount + parseFloat(depositAmount);
    const newHealthFactor = calculateHealthFactor(newCollateral, userPosition.borrowedAmount);
    
    setUserPosition({
      ...userPosition,
      collateralAmount: newCollateral,
      healthFactor: newHealthFactor,
      totalXP: userPosition.totalXP + 10,
    });
    
    setDepositAmount('');
    setIsProcessing(false);
  };

  // Borrow funds
  const handleBorrow = async () => {
    if (!borrowAmount || parseFloat(borrowAmount) <= 0) return;
    
    const maxBorrow = (userPosition.collateralAmount * 0.75) - userPosition.borrowedAmount;
    if (parseFloat(borrowAmount) > maxBorrow) {
      alert('Borrow amount exceeds maximum allowed based on collateral');
      return;
    }
    
    setIsProcessing(true);
    await new Promise(resolve => setTimeout(resolve, 2000));
    
    const newBorrowed = userPosition.borrowedAmount + parseFloat(borrowAmount);
    const newHealthFactor = calculateHealthFactor(userPosition.collateralAmount, newBorrowed);
    
    setUserPosition({
      ...userPosition,
      borrowedAmount: newBorrowed,
      healthFactor: newHealthFactor,
      totalXP: userPosition.totalXP + 20,
    });
    
    setPoolStats({
      ...poolStats,
      totalBorrowed: poolStats.totalBorrowed + parseFloat(borrowAmount),
      utilizationRate: ((poolStats.totalBorrowed + parseFloat(borrowAmount)) / poolStats.totalLiquidity) * 100,
    });
    
    setBorrowAmount('');
    setIsProcessing(false);
  };

  // Repay loan
  const handleRepay = async () => {
    if (!repayAmount || parseFloat(repayAmount) <= 0) return;
    
    setIsProcessing(true);
    await new Promise(resolve => setTimeout(resolve, 2000));
    
    const repayValue = Math.min(parseFloat(repayAmount), userPosition.borrowedAmount);
    const newBorrowed = userPosition.borrowedAmount - repayValue;
    const newHealthFactor = calculateHealthFactor(userPosition.collateralAmount, newBorrowed);
    
    setUserPosition({
      ...userPosition,
      borrowedAmount: newBorrowed,
      healthFactor: newHealthFactor,
      totalXP: userPosition.totalXP + 15,
    });
    
    setRepayAmount('');
    setIsProcessing(false);
  };

  // Withdraw collateral
  const handleWithdraw = async () => {
    if (!withdrawAmount || parseFloat(withdrawAmount) <= 0) return;
    
    const newCollateral = userPosition.collateralAmount - parseFloat(withdrawAmount);
    const newHealthFactor = calculateHealthFactor(newCollateral, userPosition.borrowedAmount);
    
    if (newHealthFactor < 1.2 && userPosition.borrowedAmount > 0) {
      alert('Cannot withdraw: would result in unhealthy position');
      return;
    }
    
    setIsProcessing(true);
    await new Promise(resolve => setTimeout(resolve, 2000));
    
    setUserPosition({
      ...userPosition,
      collateralAmount: newCollateral,
      healthFactor: newHealthFactor,
    });
    
    setWithdrawAmount('');
    setIsProcessing(false);
  };

  const getHealthFactorColor = (hf) => {
    if (hf >= 1.5) return 'text-green-500';
    if (hf >= 1.2) return 'text-yellow-500';
    return 'text-red-500';
  };

  const getHealthFactorBg = (hf) => {
    if (hf >= 1.5) return 'bg-green-500';
    if (hf >= 1.2) return 'bg-yellow-500';
    return 'bg-red-500';
  };

  // Navigation items
  const navItems = [
    { id: 'lending', label: 'Lending', icon: Home },
    { id: 'analytics', label: 'Analytics', icon: BarChart3 },
    { id: 'achievements', label: 'Achievements', icon: Trophy },
  ];

  return (
    <div className="min-h-screen bg-[#050505] text-white selection:bg-[#00ff9d]/30">
      <div className="flex">
        {/* Sidebar */}
        <div className={`
          fixed inset-y-0 left-0 z-30 bg-[#0a0a0a] border-r border-white/5 transition-transform duration-300
          ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}
          md:translate-x-0 md:w-64 w-64
        `}>
          <div className="p-4">
            {/* Logo */}
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center space-x-2">
                <Shield className="w-8 h-8 text-[#00ff9d]" />
                <span className="font-bold text-lg tracking-tight">ZKredit</span>
              </div>
              {/* Mobile Close Button */}
              <button
                onClick={() => setSidebarOpen(false)}
                className="md:hidden p-2 hover:bg-white/5 rounded-lg transition-colors text-gray-400 hover:text-white"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {/* Navigation */}
            <nav className="space-y-2">
              {navItems.map((item) => (
                  <button
                    key={item.id}
                    onClick={() => {
                      setActiveTab(item.id);
                      setSidebarOpen(false); // Close on mobile selection
                    }}
                    className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-all ${
                      activeTab === item.id
                        ? 'bg-[#00ff9d]/10 text-[#00ff9d] border border-[#00ff9d]/20'
                        : 'text-gray-400 hover:bg-white/5 hover:text-white'
                    }`}
                  >
                    <item.icon className="w-5 h-5 flex-shrink-0" />
                    <span>{item.label}</span>
                  </button>
              ))}
            </nav>

            {/* User Level (if connected) */}
            {wallet.connected && (
              <div className="mt-8 p-4 bg-white/5 rounded-lg border border-white/10">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm text-gray-400">Level {userPosition.level}</span>
                  <Trophy className="w-4 h-4 text-[#00ff9d]" />
                </div>
                <div className="w-full bg-black/50 rounded-full h-2 mb-2">
                  <div className="bg-[#00ff9d] h-2 rounded-full shadow-[0_0_10px_rgba(0,255,157,0.5)]" style={{ width: '65%' }} />
                </div>
                <p className="text-xs text-gray-400">{userPosition.totalXP} XP</p>
              </div>
            )}
          </div>
        </div>

        {/* Main Content */}

        <div className="flex-1 md:ml-64 transition-all duration-300">
          {/* Header */}
          <div className="bg-[#050505]/80 backdrop-blur-md border-b border-white/5 px-6 py-4 sticky top-0 z-20">
            <div className="flex justify-between items-center">
              <div className="flex items-center gap-4">
                {/* Mobile Menu Toggle */}
                <button
                  onClick={() => setSidebarOpen(true)}
                  className="md:hidden p-2 -ml-2 text-gray-400 hover:text-white"
                >
                  <Menu className="w-6 h-6" />
                </button>
                
                <div>
                  <h1 className="text-xl md:text-2xl font-bold text-white">
                  {activeTab === 'lending' && 'Private Lending'}
                  {activeTab === 'analytics' && 'Analytics Dashboard'}
                  {activeTab === 'achievements' && 'Achievements & Rewards'}
                </h1>
                <p className="text-sm text-gray-400 mt-1">
                  {activeTab === 'lending' && 'Deposit, borrow, and manage your encrypted positions'}
                  {activeTab === 'analytics' && 'Real-time insights with privacy-preserved data'}
                  {activeTab === 'achievements' && 'Track your progress and earn rewards'}
                </p>
              </div>
              </div>
              
              {!wallet.connected ? (
                <WalletMultiButton className="!bg-[#00ff9d] !text-black hover:!bg-[#00cc7d] !px-6 !py-3 !rounded-full !font-semibold !transition-all !shadow-[0_0_20px_rgba(0,255,157,0.2)] hover:!shadow-[0_0_30px_rgba(0,255,157,0.4)]" />
              ) : (
                <div className="flex items-center space-x-4">
                  <div className="flex items-center space-x-2 bg-white/5 border border-white/10 px-4 py-2 rounded-full">
                    <div className="w-2 h-2 bg-[#00ff9d] rounded-full animate-pulse" />
                    <span className="text-sm text-gray-300">
                      {wallet.publicKey?.toBase58().slice(0, 4)}...{wallet.publicKey?.toBase58().slice(-4)}
                    </span>
                  </div>
                  <button
                    onClick={() => setShowPrivateInfo(!showPrivateInfo)}
                    className="p-2 hover:bg-white/5 rounded-full transition-colors text-gray-400 hover:text-white"
                    title={showPrivateInfo ? 'Hide amounts' : 'Show amounts'}
                  >
                    {showPrivateInfo ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                  </button>
                  <button
                    onClick={() => wallet.disconnect()}
                    className="p-2 hover:bg-red-500/10 rounded-full transition-colors text-gray-400 hover:text-red-400 border border-transparent hover:border-red-500/30"
                    title="Disconnect wallet"
                  >
                    <LogOut className="w-5 h-5" />
                  </button>
                </div>
              )}
            </div>
          </div>

          {/* Privacy Notice */}
          <div className="px-6 pt-6">
            <div className="bg-[#00ff9d]/5 border border-[#00ff9d]/20 rounded-xl p-4 flex items-start space-x-3">
              <Lock className="w-5 h-5 text-[#00ff9d] mt-0.5 flex-shrink-0" />
              <div className="flex-1">
                <h3 className="font-semibold text-[#00ff9d] mb-1">End-to-End Privacy via Arcium MPC</h3>
                <p className="text-sm text-gray-400">
                  All positions, health factors, and calculations are encrypted. No single party can see your private data.
                </p>
              </div>
            </div>
          </div>

          {/* Content Area */}
          <div className="p-6">
            {!wallet.connected ? (
              <div className="bg-white/[0.02] border border-white/5 rounded-2xl p-12 text-center">
                <Shield className="w-16 h-16 mx-auto mb-4 text-[#00ff9d]" />
                <h2 className="text-2xl font-bold mb-2 text-white">Connect Your Wallet</h2>
                <p className="text-gray-400 mb-6">
                  Connect your Solana wallet to access private lending features
                </p>
              </div>
            ) : (
              <>
                {/* LENDING TAB */}
                {activeTab === 'lending' && (
                  <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Left Column - Stats */}
                    <div className="space-y-6">
                      {/* Protocol Stats */}
                      <div className="bg-white/[0.03] backdrop-blur-sm rounded-2xl p-6 border border-white/5">
                        <h2 className="text-xl font-bold mb-4 flex items-center text-white">
                          <TrendingUp className="w-5 h-5 mr-2 text-[#00ff9d]" />
                          Protocol Stats
                        </h2>
                        <div className="space-y-4">
                          <div>
                            <div className="text-sm text-gray-400 mb-1">Total Liquidity</div>
                            <div className="text-2xl font-bold text-white">${poolStats.totalLiquidity.toLocaleString()}</div>
                          </div>
                          <div>
                            <div className="text-sm text-gray-400 mb-1">Total Borrowed</div>
                            <div className="text-2xl font-bold text-white">${poolStats.totalBorrowed.toLocaleString()}</div>
                          </div>
                          <div>
                            <div className="text-sm text-gray-400 mb-1">Utilization Rate</div>
                            <div className="flex items-center space-x-2">
                              <div className="flex-1 bg-white/10 rounded-full h-2">
                                <div 
                                  className="bg-[#00ff9d] h-2 rounded-full shadow-[0_0_10px_rgba(0,255,157,0.3)]"
                                  style={{ width: `${poolStats.utilizationRate}%` }}
                                />
                              </div>
                              <span className="text-sm font-semibold text-[#00ff9d]">{poolStats.utilizationRate.toFixed(1)}%</span>
                            </div>
                          </div>
                          <div>
                            <div className="text-sm text-gray-400 mb-1">Average APY</div>
                            <div className="text-2xl font-bold text-[#00ff9d]">{poolStats.avgAPY}%</div>
                          </div>
                        </div>
                      </div>

                      {/* User Position */}
                      <div className="bg-white/[0.03] backdrop-blur-sm rounded-2xl p-6 border border-white/5">
                        <div className="flex justify-between items-center mb-4">
                          <h2 className="text-xl font-bold flex items-center text-white">
                            <Lock className="w-5 h-5 mr-2 text-[#00ff9d]" />
                            Your Position
                          </h2>
                        </div>
                        
                        <div className="space-y-4">
                          <div>
                            <div className="text-sm text-gray-400 mb-1">Collateral Deposited</div>
                            <div className="text-2xl font-bold">
                              {showPrivateInfo ? `$${userPosition.collateralAmount.toLocaleString()}` : '••••••'}
                            </div>
                          </div>
                          <div>
                            <div className="text-sm text-gray-400 mb-1">Amount Borrowed</div>
                            <div className="text-2xl font-bold">
                              {showPrivateInfo ? `$${userPosition.borrowedAmount.toLocaleString()}` : '••••••'}
                            </div>
                          </div>
                          <div>
                            <div className="text-sm text-gray-400 mb-1">Health Factor</div>
                            <div className={`text-2xl font-bold ${getHealthFactorColor(userPosition.healthFactor)}`}>
                              {showPrivateInfo ? userPosition.healthFactor.toFixed(2) : '•••'}
                            </div>
                            {showPrivateInfo && (
                              <div className="mt-2">
                                <div className="flex items-center justify-between text-xs text-gray-400 mb-1">
                                  <span>Safe</span>
                                  <span>At Risk</span>
                                </div>
                                <div className="w-full bg-white/10 rounded-full h-2">
                                  <div 
                                    className={`h-2 rounded-full ${getHealthFactorBg(userPosition.healthFactor)}`}
                                    style={{ width: `${Math.min(100, (userPosition.healthFactor / 2) * 100)}%` }}
                                  />
                                </div>
                              </div>
                            )}
                          </div>
                          <div>
                            <div className="text-sm text-gray-400 mb-1">Interest Rate</div>
                            <div className="text-xl font-bold">
                              {showPrivateInfo ? `${userPosition.interestRate}% APY` : '••••'}
                            </div>
                          </div>
                        </div>

                        {userPosition.healthFactor < 1.3 && userPosition.borrowedAmount > 0 && showPrivateInfo && (
                          <div className="mt-4 bg-yellow-900/30 border border-yellow-500/50 rounded-lg p-3 flex items-start space-x-2">
                            <AlertCircle className="w-5 h-5 text-yellow-400 mt-0.5 flex-shrink-0" />
                            <div>
                              <p className="text-sm text-yellow-300 font-semibold">Warning: Low Health Factor</p>
                              <p className="text-xs text-gray-300 mt-1">
                                Consider adding collateral or repaying debt
                              </p>
                            </div>
                          </div>
                        )}
                      </div>
                    </div>

                    {/* Right Column - Actions */}
                    <div className="lg:col-span-2">
                      <div className="bg-white/[0.03] backdrop-blur-sm rounded-2xl border border-white/5">
                        {/* Tabs */}
                        <div className="flex border-b border-white/5">
                          {['deposit', 'borrow', 'repay', 'withdraw'].map((tab) => (
                            <button
                              key={tab}
                              onClick={() => setActiveLendingTab(tab)}
                              className={`flex-1 py-4 px-6 font-semibold capitalize transition-colors ${
                                activeLendingTab === tab
                                  ? 'bg-[#00ff9d]/10 text-[#00ff9d] border-b-2 border-[#00ff9d]'
                                  : 'text-gray-400 hover:text-white hover:bg-white/5'
                              }`}
                            >
                              {tab}
                            </button>
                          ))}
                        </div>

                        {/* Tab Content */}
                        <div className="p-6">
                          {activeLendingTab === 'deposit' && (
                            <div className="space-y-6">
                              <div>
                                <h3 className="text-2xl font-bold mb-2 text-white">Deposit Collateral</h3>
                                <p className="text-gray-400 text-sm">
                                  Add collateral to your private position. Amount is encrypted via Arcium MPC.
                                </p>
                              </div>
                              
                              <div>
                                <label className="block text-sm font-medium mb-2 text-gray-300">Amount (USDC)</label>
                                <div className="relative">
                                  <DollarSign className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
                                  <input
                                    type="number"
                                    value={depositAmount}
                                    onChange={(e) => setDepositAmount(e.target.value)}
                                    placeholder="0.00"
                                    className="w-full bg-black/50 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-lg focus:outline-none focus:border-[#00ff9d] text-white placeholder-gray-600"
                                  />
                                </div>
                              </div>

                              <div className="bg-[#00ff9d]/5 border border-[#00ff9d]/20 rounded-xl p-4">
                                <div className="flex justify-between items-center mb-2">
                                  <span className="text-sm text-gray-300">New Collateral</span>
                                  <span className="font-semibold text-white">
                                    ${(userPosition.collateralAmount + (parseFloat(depositAmount) || 0)).toLocaleString()}
                                  </span>
                                </div>
                                <div className="flex justify-between items-center">
                                  <span className="text-sm text-gray-300">New Health Factor</span>
                                  <span className={`font-semibold ${getHealthFactorColor(
                                    calculateHealthFactor(
                                      userPosition.collateralAmount + (parseFloat(depositAmount) || 0),
                                      userPosition.borrowedAmount
                                    )
                                  )}`}>
                                    {calculateHealthFactor(
                                      userPosition.collateralAmount + (parseFloat(depositAmount) || 0),
                                      userPosition.borrowedAmount
                                    ).toFixed(2)}
                                  </span>
                                </div>
                              </div>

                              <button
                                onClick={handleDeposit}
                                disabled={isProcessing || !depositAmount || parseFloat(depositAmount) <= 0}
                                className="w-full bg-[#00ff9d] text-black hover:bg-[#00cc7d] py-4 rounded-full font-semibold text-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2 shadow-[0_0_20px_rgba(0,255,157,0.2)] hover:shadow-[0_0_30px_rgba(0,255,157,0.4)]"
                              >
                                {isProcessing ? (
                                  <>
                                    <Loader className="w-5 h-5 animate-spin" />
                                    <span>Processing...</span>
                                  </>
                                ) : (
                                  <span>Deposit Collateral</span>
                                )}
                              </button>
                            </div>
                          )}

                          {activeLendingTab === 'borrow' && (
                            <div className="space-y-6">
                              <div>
                                <h3 className="text-2xl font-bold mb-2">Borrow Funds</h3>
                                <p className="text-gray-400 text-sm">
                                  Borrow against your collateral. Loan details remain private.
                                </p>
                              </div>
                              
                              <div>
                                <label className="block text-sm font-medium mb-2 text-gray-300">Amount (USDC)</label>
                                <div className="relative">
                                  <DollarSign className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
                                  <input
                                    type="number"
                                    value={borrowAmount}
                                    onChange={(e) => setBorrowAmount(e.target.value)}
                                    placeholder="0.00"
                                    className="w-full bg-black/50 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-lg focus:outline-none focus:border-[#00ff9d] text-white placeholder-gray-600"
                                  />
                                </div>
                                <div className="mt-2 flex justify-between text-sm">
                                  <span className="text-gray-400">Available to borrow</span>
                                  <span className="font-semibold text-[#00ff9d]">
                                    ${((userPosition.collateralAmount * 0.75) - userPosition.borrowedAmount).toFixed(2)}
                                  </span>
                                </div>
                              </div>

                              <div className="bg-[#00ff9d]/5 border border-[#00ff9d]/20 rounded-xl p-4 space-y-2">
                                <div className="flex justify-between items-center">
                                  <span className="text-sm text-gray-300">Interest Rate</span>
                                  <span className="font-semibold text-white">{userPosition.interestRate}% APY</span>
                                </div>
                                <div className="flex justify-between items-center">
                                  <span className="text-sm text-gray-300">New Borrowed</span>
                                  <span className="font-semibold text-white">
                                    ${(userPosition.borrowedAmount + (parseFloat(borrowAmount) || 0)).toLocaleString()}
                                  </span>
                                </div>
                                <div className="flex justify-between items-center">
                                  <span className="text-sm text-gray-300">New Health Factor</span>
                                  <span className={`font-semibold ${getHealthFactorColor(
                                    calculateHealthFactor(
                                      userPosition.collateralAmount,
                                      userPosition.borrowedAmount + (parseFloat(borrowAmount) || 0)
                                    )
                                  )}`}>
                                    {calculateHealthFactor(
                                      userPosition.collateralAmount,
                                      userPosition.borrowedAmount + (parseFloat(borrowAmount) || 0)
                                    ).toFixed(2)}
                                  </span>
                                </div>
                              </div>

                              <button
                                onClick={handleBorrow}
                                disabled={isProcessing || !borrowAmount || parseFloat(borrowAmount) <= 0}
                                className="w-full bg-[#00ff9d] text-black hover:bg-[#00cc7d] py-4 rounded-full font-semibold text-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2 shadow-[0_0_20px_rgba(0,255,157,0.2)] hover:shadow-[0_0_30px_rgba(0,255,157,0.4)]"
                              >
                                {isProcessing ? (
                                  <>
                                    <Loader className="w-5 h-5 animate-spin" />
                                    <span>Processing...</span>
                                  </>
                                ) : (
                                  <span>Borrow Funds</span>
                                )}
                              </button>
                            </div>
                          )}

                          {activeLendingTab === 'repay' && (
                            <div className="space-y-6">
                              <div>
                                <h3 className="text-2xl font-bold mb-2">Repay Loan</h3>
                                <p className="text-gray-400 text-sm">
                                  Repay your borrowed amount to improve your health factor.
                                </p>
                              </div>
                              
                              <div>
                                <label className="block text-sm font-medium mb-2 text-gray-300">Amount (USDC)</label>
                                <div className="relative">
                                  <DollarSign className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
                                  <input
                                    type="number"
                                    value={repayAmount}
                                    onChange={(e) => setRepayAmount(e.target.value)}
                                    placeholder="0.00"
                                    className="w-full bg-black/50 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-lg focus:outline-none focus:border-[#00ff9d] text-white placeholder-gray-600"
                                  />
                                </div>
                                <div className="mt-2 flex justify-between text-sm">
                                  <span className="text-gray-400">Total debt</span>
                                  <span className="font-semibold text-red-400">
                                    ${userPosition.borrowedAmount.toLocaleString()}
                                  </span>
                                </div>
                              </div>

                              <div className="bg-[#00ff9d]/5 border border-[#00ff9d]/20 rounded-xl p-4 space-y-2">
                                <div className="flex justify-between items-center">
                                  <span className="text-sm text-gray-300">Remaining Debt</span>
                                  <span className="font-semibold text-white">
                                    ${Math.max(0, userPosition.borrowedAmount - (parseFloat(repayAmount) || 0)).toLocaleString()}
                                  </span>
                                </div>
                                <div className="flex justify-between items-center">
                                  <span className="text-sm text-gray-300">New Health Factor</span>
                                  <span className={`font-semibold ${getHealthFactorColor(
                                    calculateHealthFactor(
                                      userPosition.collateralAmount,
                                      Math.max(0, userPosition.borrowedAmount - (parseFloat(repayAmount) || 0))
                                    )
                                  )}`}>
                                    {calculateHealthFactor(
                                      userPosition.collateralAmount,
                                      Math.max(0, userPosition.borrowedAmount - (parseFloat(repayAmount) || 0))
                                    ).toFixed(2)}
                                  </span>
                                </div>
                              </div>

                              <button
                                onClick={handleRepay}
                                disabled={isProcessing || !repayAmount || parseFloat(repayAmount) <= 0 || userPosition.borrowedAmount === 0}
                                className="w-full bg-[#00ff9d] text-black hover:bg-[#00cc7d] py-4 rounded-full font-semibold text-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2 shadow-[0_0_20px_rgba(0,255,157,0.2)] hover:shadow-[0_0_30px_rgba(0,255,157,0.4)]"
                              >
                                {isProcessing ? (
                                  <>
                                    <Loader className="w-5 h-5 animate-spin" />
                                    <span>Processing...</span>
                                  </>
                                ) : (
                                  <span>Repay Loan</span>
                                )}
                              </button>
                            </div>
                          )}

                          {activeLendingTab === 'withdraw' && (
                            <div className="space-y-6">
                              <div>
                                <h3 className="text-2xl font-bold mb-2">Withdraw Collateral</h3>
                                <p className="text-gray-400 text-sm">
                                  Withdraw your collateral. Must maintain healthy position if you have an active loan.
                                </p>
                              </div>
                              
                              <div>
                                <label className="block text-sm font-medium mb-2 text-gray-300">Amount (USDC)</label>
                                <div className="relative">
                                  <DollarSign className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-gray-400" />
                                  <input
                                    type="number"
                                    value={withdrawAmount}
                                    onChange={(e) => setWithdrawAmount(e.target.value)}
                                    placeholder="0.00"
                                    className="w-full bg-black/50 border border-white/10 rounded-xl pl-10 pr-4 py-3 text-lg focus:outline-none focus:border-[#00ff9d] text-white placeholder-gray-600"
                                  />
                                </div>
                                <div className="mt-2 flex justify-between text-sm">
                                  <span className="text-gray-400">Total collateral</span>
                                  <span className="font-semibold text-[#00ff9d]">
                                    ${userPosition.collateralAmount.toLocaleString()}
                                  </span>
                                </div>
                              </div>

                              <div className="bg-[#00ff9d]/5 border border-[#00ff9d]/20 rounded-xl p-4 space-y-2">
                                <div className="flex justify-between items-center">
                                  <span className="text-sm text-gray-300">Remaining Collateral</span>
                                  <span className="font-semibold text-white">
                                    ${Math.max(0, userPosition.collateralAmount - (parseFloat(withdrawAmount) || 0)).toLocaleString()}
                                  </span>
                                </div>
                                <div className="flex justify-between items-center">
                                  <span className="text-sm text-gray-300">New Health Factor</span>
                                  <span className={`font-semibold ${getHealthFactorColor(
                                    calculateHealthFactor(
                                      Math.max(0, userPosition.collateralAmount - (parseFloat(withdrawAmount) || 0)),
                                      userPosition.borrowedAmount
                                    )
                                  )}`}>
                                    {calculateHealthFactor(
                                      Math.max(0, userPosition.collateralAmount - (parseFloat(withdrawAmount) || 0)),
                                      userPosition.borrowedAmount
                                    ).toFixed(2)}
                                  </span>
                                </div>
                              </div>

                              {userPosition.borrowedAmount > 0 && (
                                <div className="bg-yellow-900/20 border border-yellow-500/30 rounded-xl p-3 flex items-start space-x-2">
                                  <AlertCircle className="w-5 h-5 text-yellow-400 mt-0.5 flex-shrink-0" />
                                  <p className="text-sm text-yellow-300">
                                    Withdrawing collateral while having an active loan may decrease your health factor
                                  </p>
                                </div>
                              )}

                              <button
                                onClick={handleWithdraw}
                                disabled={isProcessing || !withdrawAmount || parseFloat(withdrawAmount) <= 0 || userPosition.collateralAmount === 0}
                                className="w-full bg-[#00ff9d] text-black hover:bg-[#00cc7d] py-4 rounded-full font-semibold text-lg transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center space-x-2 shadow-[0_0_20px_rgba(0,255,157,0.2)] hover:shadow-[0_0_30px_rgba(0,255,157,0.4)]"
                              >
                                {isProcessing ? (
                                  <>
                                    <Loader className="w-5 h-5 animate-spin" />
                                    <span>Processing...</span>
                                  </>
                                ) : (
                                  <span>Withdraw Collateral</span>
                                )}
                              </button>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                )}

                {/* ANALYTICS TAB */}
                {activeTab === 'analytics' && (
                  <div className="space-y-6">
                    {/* Key Metrics Row */}
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                      <div className="bg-black/40 border border-white/10 rounded-xl p-4">
                        <div className="flex items-center justify-between mb-2">
                          <span className="text-gray-400 text-sm">TVL</span>
                          <TrendingUp className="w-4 h-4 text-[#00ff9d]" />
                        </div>
                        <div className="text-2xl font-bold text-white">${poolStats.totalLiquidity.toLocaleString()}</div>
                        <div className="text-sm text-[#00ff9d]">+12.5%</div>
                      </div>
                      <div className="bg-black/40 border border-white/10 rounded-xl p-4">
                        <div className="flex items-center justify-between mb-2">
                          <span className="text-gray-400 text-sm">Active Positions</span>
                          <Users className="w-4 h-4 text-blue-400" />
                        </div>
                        <div className="text-2xl font-bold text-white">1,234</div>
                        <div className="text-sm text-[#00ff9d]">+8.2%</div>
                      </div>
                      <div className="bg-black/40 border border-white/10 rounded-xl p-4">
                        <div className="flex items-center justify-between mb-2">
                          <span className="text-gray-400 text-sm">Avg Health</span>
                          <Activity className="w-4 h-4 text-purple-400" />
                        </div>
                        <div className="text-2xl font-bold text-white">1.85</div>
                        <div className="text-sm text-[#00ff9d]">+0.15</div>
                      </div>
                      <div className="bg-black/40 border border-white/10 rounded-xl p-4">
                        <div className="flex items-center justify-between mb-2">
                          <span className="text-gray-400 text-sm">Liquidations (24h)</span>
                          <AlertCircle className="w-4 h-4 text-red-400" />
                        </div>
                        <div className="text-2xl font-bold text-white">3</div>
                        <div className="text-sm text-[#00ff9d]">-2</div>
                      </div>
                    </div>

                    {/* Charts */}
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                      {/* Health Factor Chart */}
                      <div className="bg-black/40 border border-white/10 rounded-xl p-6">
                        <h3 className="text-lg font-bold mb-4 text-white">Your Health Factor Trend</h3>
                        <div style={{ width: '100%', height: '256px' }}>
                          <ResponsiveContainer>
                            <AreaChart
                              data={healthFactorHistory}
                              margin={{ top: 10, right: 10, left: 0, bottom: 0 }}
                            >
                              <defs>
                                <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                                  <stop offset="5%" stopColor="#00ff9d" stopOpacity={0.3}/>
                                  <stop offset="95%" stopColor="#00ff9d" stopOpacity={0}/>
                                </linearGradient>
                              </defs>
                              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" vertical={false} />
                              <XAxis 
                                dataKey="time" 
                                axisLine={false}
                                tickLine={false}
                                tick={{ fill: '#9ca3af', fontSize: 12 }}
                                dy={10}
                              />
                              <YAxis 
                                axisLine={false}
                                tickLine={false}
                                tick={{ fill: '#9ca3af', fontSize: 12 }}
                                domain={[0, 3]}
                              />
                              <Tooltip 
                                contentStyle={{ 
                                  backgroundColor: '#0a0a0a', 
                                  border: '1px solid rgba(255,255,255,0.1)',
                                  borderRadius: '8px',
                                  color: '#fff'
                                }}
                                itemStyle={{ color: '#00ff9d' }}
                                labelStyle={{ color: '#9ca3af', marginBottom: '0.5rem' }}
                              />
                              <Area 
                                type="monotone" 
                                dataKey="value" 
                                stroke="#00ff9d" 
                                strokeWidth={2}
                                fillOpacity={1} 
                                fill="url(#colorValue)" 
                              />
                            </AreaChart>
                          </ResponsiveContainer>
                        </div>
                      </div>

                      {/* Risk Distribution */}
                      <div className="bg-black/40 border border-white/10 rounded-xl p-6">
                        <h3 className="text-lg font-bold mb-4 text-white">Risk Distribution</h3>
                        <div className="space-y-4">
                          {[
                            { label: 'Low Risk', count: 850, color: 'bg-[#00ff9d]', percentage: 68.9 },
                            { label: 'Medium Risk', count: 280, color: 'bg-yellow-500', percentage: 22.7 },
                            { label: 'High Risk', count: 84, color: 'bg-orange-500', percentage: 6.8 },
                            { label: 'Critical', count: 20, color: 'bg-red-500', percentage: 1.6 },
                          ].map((item, idx) => (
                            <div key={idx}>
                              <div className="flex justify-between text-sm mb-1">
                                <span className="text-gray-300">{item.label}</span>
                                <span className="font-semibold text-white">{item.count} ({item.percentage}%)</span>
                              </div>
                              <div className="w-full bg-white/10 rounded-full h-2">
                                <div className={`${item.color} h-2 rounded-full`} style={{ width: `${item.percentage}%` }} />
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>

                    {/* Activity Feed */}
                    <div className="bg-black/40 border border-white/10 rounded-xl p-6">
                      <h3 className="text-lg font-bold mb-4 text-white">Recent Protocol Activity</h3>
                      <div className="space-y-3">
                        {[
                          { type: 'deposit', user: '7x9K...mP4L', action: 'Deposited collateral', time: '2 min ago' },
                          { type: 'borrow', user: 'Ak2m...8Qw3', action: 'Borrowed funds', time: '5 min ago' },
                          { type: 'repay', user: 'Fj5n...Lr9P', action: 'Repaid loan', time: '12 min ago' },
                          { type: 'liquidation', user: 'Position #4829', action: 'Liquidated', time: '18 min ago' },
                        ].map((activity, idx) => (
                          <div key={idx} className="flex items-center justify-between p-3 bg-white/5 rounded-lg border border-white/5 hover:border-white/10 transition-colors">
                            <div className="flex items-center space-x-3">
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center ${
                                activity.type === 'deposit' ? 'bg-[#00ff9d]/20 text-[#00ff9d]' :
                                activity.type === 'borrow' ? 'bg-blue-500/20 text-blue-400' :
                                activity.type === 'repay' ? 'bg-purple-500/20 text-purple-400' :
                                'bg-red-500/20 text-red-400'
                              }`}>
                                {activity.type === 'deposit' && '↓'}
                                {activity.type === 'borrow' && '→'}
                                {activity.type === 'repay' && '←'}
                                {activity.type === 'liquidation' && '⚠'}
                              </div>
                              <div>
                                <div className="font-semibold text-sm text-white">{activity.user}</div>
                                <div className="text-xs text-gray-400">{activity.action} (Encrypted)</div>
                              </div>
                            </div>
                            <span className="text-xs text-gray-400">{activity.time}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                )}

                {/* ACHIEVEMENTS TAB */}
                {activeTab === 'achievements' && (
                  <div className="space-y-6">
                    {/* Progress Overview */}
                    <div className="bg-[#00ff9d]/5 border border-[#00ff9d]/20 rounded-xl p-6">
                      <div className="flex items-center justify-between mb-4">
                        <div>
                          <h2 className="text-2xl font-bold text-white">Level {userPosition.level}</h2>
                          <p className="text-gray-400">Keep lending to level up!</p>
                        </div>
                        <Trophy className="w-12 h-12 text-yellow-400" />
                      </div>
                      <div className="space-y-2">
                        <div className="flex justify-between text-sm">
                          <span className="text-gray-300">Progress to Level {userPosition.level + 1}</span>
                          <span className="text-[#00ff9d] font-semibold">{userPosition.totalXP} / 1500 XP</span>
                        </div>
                        <div className="w-full bg-white/10 rounded-full h-3">
                          <div 
                            className="bg-gradient-to-r from-[#00ff9d] to-[#00cc7d] h-3 rounded-full shadow-[0_0_10px_rgba(0,255,157,0.3)]"
                            style={{ width: `${(userPosition.totalXP / 1500) * 100}%` }}
                          />
                        </div>
                      </div>
                    </div>

                    {/* Stats Grid */}
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div className="bg-black/40 border border-white/10 rounded-xl p-4 text-center">
                        <div className="text-3xl font-bold text-yellow-400 mb-1">{userPosition.streak}</div>
                        <div className="text-sm text-gray-400">Day Streak 🔥</div>
                      </div>
                      <div className="bg-black/40 border border-white/10 rounded-xl p-4 text-center">
                        <div className="text-3xl font-bold text-[#00ff9d] mb-1">
                          {achievements.filter(a => a.unlocked).length}
                        </div>
                        <div className="text-sm text-gray-400">Achievements Unlocked</div>
                      </div>
                      <div className="bg-black/40 border border-white/10 rounded-xl p-4 text-center">
                        <div className="text-3xl font-bold text-purple-400 mb-1">{userPosition.totalXP}</div>
                        <div className="text-sm text-gray-400">Total XP Earned</div>
                      </div>
                    </div>

                    {/* Achievements List */}
                    <div className="bg-black/40 border border-white/10 rounded-xl p-6">
                      <h3 className="text-xl font-bold mb-4 text-white">Your Achievements</h3>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {achievements.map((achievement) => (
                          <div 
                            key={achievement.id}
                            className={`p-4 rounded-xl border transition-all ${
                              achievement.unlocked
                                ? 'bg-[#00ff9d]/5 border-[#00ff9d]/30 shadow-[0_0_15px_rgba(0,255,157,0.1)]'
                                : 'bg-white/5 border-white/5 opacity-60'
                            }`}
                          >
                            <div className="flex items-start justify-between mb-2">
                              <div className="text-2xl">{achievement.title.split(' ')[0]}</div>
                              {achievement.unlocked && <CheckCircle className="w-5 h-5 text-[#00ff9d]" />}
                            </div>
                            <h4 className="font-semibold mb-1 text-white">{achievement.title.substring(2)}</h4>
                            <div className="flex items-center justify-between">
                              <span className="text-sm text-gray-400">
                                {achievement.unlocked ? 'Unlocked!' : 'Locked'}
                              </span>
                              <span className="text-sm font-semibold text-yellow-400">
                                +{achievement.points} XP
                              </span>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>

                    {/* Leaderboard */}
                    <div className="bg-black/40 border border-white/10 rounded-xl p-6">
                      <h3 className="text-xl font-bold mb-4 text-white">Top Lenders</h3>
                      <div className="space-y-3">
                        {[
                          { rank: 1, user: 'Bm8k...3Tn2', level: 12, xp: 5420 },
                          { rank: 2, user: 'Ak2m...8Qw3', level: 10, xp: 4250 },
                          { rank: 3, user: 'Fj5n...Lr9P', level: 8, xp: 3180 },
                          { rank: 4, user: '7x9K...mP4L', level: 5, xp: 1250, highlight: true },
                          { rank: 5, user: 'Zp4k...9Xm1', level: 5, xp: 1120 },
                        ].map((entry) => (
                          <div 
                            key={entry.rank}
                            className={`flex items-center justify-between p-3 rounded-lg border ${
                              entry.highlight
                                ? 'bg-[#00ff9d]/10 border-[#00ff9d]/30'
                                : 'bg-white/5 border-transparent'
                            }`}
                          >
                            <div className="flex items-center space-x-4">
                              <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold ${
                                entry.rank === 1 ? 'bg-yellow-500 text-black' :
                                entry.rank === 2 ? 'bg-gray-400 text-black' :
                                entry.rank === 3 ? 'bg-orange-600 text-white' :
                                'bg-white/10 text-gray-300'
                              }`}>
                                {entry.rank}
                              </div>
                              <div>
                                <div className="font-semibold text-white">{entry.user}</div>
                                <div className="text-xs text-gray-400">Level {entry.level}</div>
                              </div>
                            </div>
                            <div className="text-right">
                              <div className="font-semibold text-[#00ff9d]">{entry.xp} XP</div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  )
};

export default ArciumPrivateLending;